'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('sv-SE').format(n), shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const SAVE='quizstorm-v01';let game=null,active=null,undo=null,hold=null,pickerIndex=null,noticeTimer=null,roundTransitioning=false;
let settings={names:['Spelare 1','Spelare 2'],seconds:20,finalSeconds:45,starter:0,difficulty:'normal'};
try{const saved=JSON.parse(localStorage.getItem(SAVE));if(saved?.version===1 && Array.isArray(saved.players)&&saved.players.length>=2){game=saved;game.difficulty||='normal';game.roundCategories||=(game.board||[]).map(c=>c.id);game.usedAnswers=(game.usedAnswers||[]).map(answerKey);for(const c of game.board||[])for(const q of c.cells)q.key=answerKey(q.answer);active=game.active||null;if(active){active.running=false;active.question.key=answerKey(active.question.answer)}if(game.final)game.final.running=false}}catch{}
const snapshot=()=>JSON.parse(JSON.stringify({game,active}));
function save(){if(!game)return;game.active=active;try{localStorage.setItem(SAVE,JSON.stringify(game))}catch{}}
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function closeModal(){document.body.classList.remove('clue-open');const d=$('#dialog');if(d.open)d.close();d.innerHTML=''}
function modal(html,clue=false){document.body.classList.toggle('clue-open',clue);const d=$('#dialog');d.classList.toggle('clue-dialog',clue);d.innerHTML=html;if(!d.open)d.showModal();}
function soundButton(){return `<button class="subtle" data-sound-toggle aria-pressed="${QuizEffects.enabled}" onclick="toggleSound()">${QuizEffects.enabled?'Ljud på':'Ljud av'}</button>`}
function toggleSound(){QuizEffects.toggle();if(!QuizEffects.enabled)return;if(game?.phase==='final'&&game.final?.stage==='clue'&&game.final.running)QuizEffects.startFinalThinking(game.finalSeconds||45,false);else if(game?.phase==='result')QuizEffects.celebrate('winner');else if(!document.body.classList.contains('playing'))QuizEffects.menuMusic(false)}
function header(){return `<header class="topbar"><div class="brand">Quiz<span>Storm</span> <span class="version">0.19</span></div><div class="sound-controls">${soundButton()}<button class="subtle" onclick="showRules()">Spelregler</button></div></header>`}
function menuScene(){return `<div class="menu-stage"><div class="menu-scene" aria-hidden="true"><div class="menu-bg-glow menu-glow-a"></div><div class="menu-bg-glow menu-glow-b"></div><img class="menu-layer menu-smoke smoke-back-1 drift-soft" decoding="async" draggable="false" style="--drift:74s;--pulse:34s;--phase:-7s" src="assets/menu-live/mist-1.webp" alt=""><img class="menu-layer menu-smoke smoke-back-2 drift-alt" decoding="async" draggable="false" style="--drift:81s;--pulse:37s;--phase:-14s" src="assets/menu-live/mist-2.webp" alt=""><img class="menu-layer menu-mountain drift-slower" decoding="async" draggable="false" style="--drift:52s;--pulse:40s;--phase:-21s" src="assets/menu-live/mountain.webp" alt=""><img class="menu-layer menu-person menu-elon drift-soft" decoding="async" draggable="false" style="--drift:55s;--pulse:43s;--phase:-28s" src="assets/menu-live/elon.webp" alt=""><img class="menu-layer menu-person menu-mozart drift-alt" decoding="async" draggable="false" style="--drift:58s;--pulse:46s;--phase:-35s" src="assets/menu-live/mozart.webp" alt=""><img class="menu-layer menu-person menu-saladin drift-soft" decoding="async" draggable="false" style="--drift:61s;--pulse:49s;--phase:-42s" src="assets/menu-live/saladin.webp" alt=""><img class="menu-layer menu-person menu-einstein drift-alt" decoding="async" draggable="false" style="--drift:64s;--pulse:31s;--phase:-49s" src="assets/menu-live/einstein.webp" alt=""><img class="menu-layer menu-person menu-astrid drift-soft" decoding="async" draggable="false" style="--drift:67s;--pulse:34s;--phase:-3s" src="assets/menu-live/astrid.webp" alt=""><img class="menu-layer menu-icon menu-globe drift-slower glow-soft" decoding="async" draggable="false" style="--drift:70s;--pulse:37s;--phase:-10s" src="assets/menu-live/globe.webp" alt=""><img class="menu-layer menu-icon menu-shuttle drift-soft" decoding="async" draggable="false" style="--drift:73s;--pulse:40s;--phase:-17s" src="assets/menu-live/shuttle.webp" alt=""><img class="menu-layer menu-icon menu-knight drift-alt" decoding="async" draggable="false" style="--drift:43s;--pulse:43s;--phase:-24s" src="assets/menu-live/knight.webp" alt=""><img class="menu-layer menu-icon menu-book drift-soft" decoding="async" draggable="false" style="--drift:46s;--pulse:46s;--phase:-31s" src="assets/menu-live/book.webp" alt=""><img class="menu-layer menu-icon menu-birds drift-alt" decoding="async" draggable="false" style="--drift:49s;--pulse:49s;--phase:-38s" src="assets/menu-live/birds.webp" alt=""><div class="menu-floaters"><img class="floater drift-soft pulse-soft floater-fe" decoding="async" draggable="false" style="--drift:52s;--pulse:31s;--phase:-45s" src="assets/menu-live/fe.webp" alt=""><img class="floater drift-alt pulse-soft floater-na" decoding="async" draggable="false" style="--drift:55s;--pulse:34s;--phase:-52s" src="assets/menu-live/na.webp" alt=""><img class="floater drift-soft pulse-soft floater-o" decoding="async" draggable="false" style="--drift:58s;--pulse:37s;--phase:-6s" src="assets/menu-live/o.webp" alt=""><img class="floater drift-alt pulse-soft floater-au" decoding="async" draggable="false" style="--drift:61s;--pulse:40s;--phase:-13s" src="assets/menu-live/au.webp" alt=""><img class="floater drift-soft pulse-soft floater-h" decoding="async" draggable="false" style="--drift:64s;--pulse:43s;--phase:-20s" src="assets/menu-live/h.webp" alt=""><img class="floater drift-alt pulse-soft floater-he" decoding="async" draggable="false" style="--drift:67s;--pulse:46s;--phase:-27s" src="assets/menu-live/he.webp" alt=""><img class="floater drift-soft pulse-soft floater-pi" decoding="async" draggable="false" style="--drift:70s;--pulse:49s;--phase:-34s" src="assets/menu-live/pi.webp" alt=""><img class="floater drift-alt pulse-soft floater-sqrt" decoding="async" draggable="false" style="--drift:73s;--pulse:31s;--phase:-41s" src="assets/menu-live/sqrt.webp" alt=""><img class="floater drift-soft pulse-soft floater-sigma" decoding="async" draggable="false" style="--drift:43s;--pulse:34s;--phase:-48s" src="assets/menu-live/sigma.webp" alt=""><img class="floater drift-alt pulse-soft floater-plus" decoding="async" draggable="false" style="--drift:46s;--pulse:37s;--phase:-2s" src="assets/menu-live/plus.webp" alt=""><img class="floater drift-soft pulse-soft floater-times" decoding="async" draggable="false" style="--drift:49s;--pulse:40s;--phase:-9s" src="assets/menu-live/times.webp" alt=""></div><img class="menu-layer menu-smoke smoke-front-1 drift-soft" decoding="async" draggable="false" style="--drift:74s;--pulse:43s;--phase:-16s" src="assets/menu-live/mist-3.webp" alt=""><img class="menu-layer menu-smoke smoke-front-2 drift-alt" decoding="async" draggable="false" style="--drift:81s;--pulse:46s;--phase:-23s" src="assets/menu-live/mist-4.webp" alt=""><img class="menu-layer menu-smoke smoke-front-3 drift-slower" decoding="async" draggable="false" style="--drift:88s;--pulse:49s;--phase:-30s" src="assets/menu-live/mist-5.webp" alt=""><img class="menu-layer menu-smoke smoke-front-4" decoding="async" draggable="false" style="--drift:95s;--pulse:31s;--phase:-37s" src="assets/menu-live/mist-6.webp" alt=""></div><div class="menu-grid"><section class="intro"><div class="eyebrow">Samla gänget. Välj din kategori.</div><h1>Quiz<span>Storm</span></h1><div class="creator-credit">Skapat av Oscar Hultgren</div></section>`}

function readSetup(){document.querySelectorAll('[data-name]').forEach(el=>settings.names[+el.dataset.name]=el.value);settings.seconds=+($('#seconds')?.value||settings.seconds);settings.finalSeconds=+($('#finalSeconds')?.value||settings.finalSeconds);settings.starter=+($('#starter')?.value||0);settings.difficulty=$('#difficulty')?.value||settings.difficulty}
function changeCount(n){readSetup();if(n>0&&settings.names.length<8)settings.names.push('Spelare '+(settings.names.length+1));if(n<0&&settings.names.length>2)settings.names.pop();settings.starter=Math.min(settings.starter,settings.names.length-1);renderMenu(true)}
function renderMenu(preserveMusic=false){if(!preserveMusic)QuizEffects.stopPersistent();document.body.classList.remove('playing');$('#app').innerHTML=`<main class="shell menu-shell">${header()}${menuScene()}<section class="panel menu-config-panel"><div class="panel-head"><h2>Nytt spel</h2><div class="stepper"><button aria-label="Ta bort en spelare" onclick="changeCount(-1)" ${settings.names.length===2?'disabled':''}>−</button><span>${settings.names.length}</span><button aria-label="Lägg till en spelare" onclick="changeCount(1)" ${settings.names.length===8?'disabled':''}>+</button></div></div><div class="names">${settings.names.map((n,i)=>`<div class="name-input"><label for="name${i}">Spelare ${i+1}</label><input id="name${i}" data-name="${i}" value="${esc(n)}" maxlength="24" autocomplete="off" oninput="updateStarterNames()"></div>`).join('')}</div><div class="form-section settings"><div><label for="seconds">Svarstid</label><select id="seconds">${[5,10,20,30].map(n=>`<option ${n===settings.seconds?'selected':''} value="${n}">${n} sekunder</option>`).join('')}</select></div><div><label for="finalSeconds">Finaltid</label><select id="finalSeconds">${[30,45,60].map(n=>`<option ${n===settings.finalSeconds?'selected':''} value="${n}">${n} sekunder</option>`).join('')}</select></div></div><div class="stack form-section difficulty-section"><label for="difficulty">Svårighetsgrad</label><select id="difficulty"><option value="easy" ${settings.difficulty==='easy'?'selected':''}>Lätt</option><option value="normal" ${settings.difficulty==='normal'?'selected':''}>Normal</option><option value="hard" ${settings.difficulty==='hard'?'selected':''}>Svår</option></select></div><div class="stack form-section"><label for="starter">Vem väljer första rutan?</label><select id="starter">${settings.names.map((n,i)=>`<option value="${i}" ${i===settings.starter?'selected':''}>${esc(n||'Spelare '+(i+1))}</option>`).join('')}</select></div><p id="setup-error" class="error" role="alert"></p><button class="primary wide start" onclick="startGame()">Starta spelet <span aria-hidden="true">→</span></button>${game?'<button class="wide subtle" style="margin-top:10px" onclick="resumeGame()">Fortsätt pågående parti</button>':''}</section></div></div></main>`;QuizEffects.menuMusic(false)}
function updateStarterNames(){const el=$('#starter');if(!el)return;const chosen=el.value;document.querySelectorAll('[data-name]').forEach(input=>{el.options[+input.dataset.name].textContent=input.value||'Spelare '+(+input.dataset.name+1)});el.value=chosen}
function startGame(){readSetup();settings.names=settings.names.map(n=>n.trim());if(settings.names.some(n=>!n)){$('#setup-error').textContent='Fyll i ett namn för varje spelare.';return}if(new Set(settings.names.map(n=>n.toLocaleLowerCase('sv'))).size!==settings.names.length){$('#setup-error').textContent='Använd olika namn så att poängen hamnar på rätt spelare.';return}if(game&&game.phase!=='result'){modal(`<h2>Starta ett nytt parti?</h2><p class="message">Det pågående partiet ersätts.</p><div class="judge"><button onclick="closeModal()">Avbryt</button><button class="primary" onclick="createGame()">Starta nytt</button></div>`)}else createGame()}
function createGame(){QuizEffects.stopPersistent();QuizEffects.unlock();closeModal();undo=null;active=null;game={version:1,bankVersion:'0.6',difficulty:settings.difficulty,phase:'board',round:1,players:settings.names.map(name=>({name,score:0})),seconds:settings.seconds,finalSeconds:settings.finalSeconds,chooser:settings.starter,usedCategories:[],usedAnswers:[],locked:false,board:[],final:null};makeBoard();save();render();QuizEffects.gameLaunch()}
function makeBoard(){const candidates=BANK.filter(c=>!game.usedCategories.includes(c.id));const seen=new Set(game.usedAnswers);game.board=shuffle(candidates).slice(0,6).map(c=>drawCategory(c,seen));game.roundCategories=game.board.map(c=>c.id);game.doubleCell=Math.floor(Math.random()*30);game.locked=false;}
function poolLevelFor(tileLevel,difficulty=game?.difficulty||'normal'){const maps={easy:[0,1,2,2,2],normal:[0,1,2,3,4],hard:[2,3,3,4,4]};return (maps[difficulty]||maps.normal)[tileLevel]}
function drawCategory(c,seen){return {id:c.id,name:c.name,cells:c.levels.map((_,l)=>{const poolLevel=poolLevelFor(l);const pool=c.levels[poolLevel];const q=shuffle(pool).find(q=>!seen.has(answerKey(q.key)));if(!q)throw Error('Frågebanken behöver fler unika facit.');seen.add(answerKey(q.key));return {...q,value:(l+1)*100*game.round,difficultyLevel:poolLevel+1,done:false}})}}
function render(){if(!game)return renderMenu();document.body.classList.add('playing');if(game.phase==='board')renderBoard();else if(game.phase==='final')renderFinal();else renderResults()}
function resumeGame(){QuizEffects.unlock();QuizEffects.stopMenu(true);render();if(active)showActive();else if(game?.phase==='board')QuizEffects.roundIntro()}
function scores(){return `<div class="scores" aria-label="Spelarnas poäng">${game.players.map((p,i)=>`<div class="score ${i===game.chooser?'active':''}" aria-label="${esc(p.name)}, ${fmt(p.score)} poäng${i===game.chooser?', väljer nästa ruta':''}"><button class="score-name score-edit" aria-label="Justera poäng för ${esc(p.name)}. Håll inne i en sekund." onpointerdown="beginScoreHold(event,${i})" onpointerup="cancelHold()" onpointerleave="cancelHold()" onpointercancel="cancelHold()" oncontextmenu="event.preventDefault()" onkeydown="scoreKey(event,${i})">${esc(p.name)}</button><strong class="${p.score<0?'negative':''}">${fmt(p.score)}</strong></div>`).join('')}</div>`}
function renderBoard(){const completed=game.board.flatMap(c=>c.cells).filter(q=>q.done).length;$('#app').innerHTML=`<main class="shell board-shell"><div class="board-control-row"><span class="eyebrow">Omgång ${game.round} · ${game.difficulty==='easy'?'Lätt':game.difficulty==='hard'?'Svår':'Normal'}</span><div class="board-corner-controls"><button class="icon-control" aria-label="Slumpa alla kategorier" title="Slumpa alla kategorier" onclick="rerollBoard()" ${game.locked?'disabled':''}>🎲</button><button class="icon-control round-skip" aria-label="Avsluta aktuell omgång" title="Avsluta aktuell omgång" onclick="confirmEndRound()">→</button></div></div>${scores()}<div class="board-wrap" aria-label="Spelplan. Svep åt sidan på en smal skärm."><div class="board">${game.board.map((c,ci)=>`<section class="category-col" aria-label="${esc(c.name)}"><button class="category" aria-label="${esc(c.name)}${game.locked?', låst':', håll inne för att byta'}" onpointerdown="beginHold(event,${ci})" onpointerup="cancelHold()" onpointerleave="cancelHold()" onpointercancel="cancelHold()" oncontextmenu="event.preventDefault()" onkeydown="categoryKey(event,${ci})"><span class="category-label">${esc(c.name)}</span></button>${c.cells.map((q,li)=>`<button class="tile ${q.done?'tile-spent':''}" ${q.done?'disabled':''} aria-label="${esc(c.name)}, ${q.value} poäng${q.done?', spelad':''}" onclick="openClue(${ci},${li})">${q.done?'<img class="played-tile-art" src="assets/played-tile.png" alt="" aria-hidden="true" draggable="false">':fmt(q.value)}</button>`).join('')}</section>`).join('')}</div></div><div class="toolbar"><div class="sound-controls"><button class="subtle" onclick="showRules()">Spelregler</button>${soundButton()}</div>${completed===30?`<button class="primary" onclick="nextRound()">${game.round===3?'Till finalen':'Nästa omgång'} →</button>`:'<button class="subtle" onclick="showTools()">Spelmeny</button>'}</div></main>`}
function beginScoreHold(e,i){if(e.button!==0||active||game.phase!=='board')return;cancelHold();hold=setTimeout(()=>{hold=null;openScoreEditor(i)},1000)}
function scoreKey(e,i){if(e.key==='Enter'||e.key===' '){e.preventDefault();openScoreEditor(i)}}
function openScoreEditor(i){if(!game||game.phase!=='board'||active||!game.players[i])return;modal(`<div class="dialog-head"><h2>Justera poäng</h2><button class="close" aria-label="Stäng" onclick="closeModal()">×</button></div><div class="stack"><label for="score-correction">Ny poängsumma för ${esc(game.players[i].name)}</label><input id="score-correction" type="text" inputmode="text" value="${game.players[i].score}" autocomplete="off" spellcheck="false"><p class="hint">Ange hela poängsumman. Minuspoäng är tillåtna.</p><p class="error" id="score-error" role="alert"></p><div class="judge"><button onclick="closeModal()">Avbryt</button><button class="primary" onclick="saveScoreCorrection(${i})">Spara poäng</button></div></div>`)}
function saveScoreCorrection(i){if(!game||game.phase!=='board'||active||!game.players[i])return;const raw=$('#score-correction').value.trim().replace(/−/g,'-').replace(/\s/g,'');const value=Number(raw);if(!/^[+-]?[0-9]+$/.test(raw)||!Number.isSafeInteger(value)){$('#score-error').textContent='Ange en giltig poängsumma i hela poäng, exempelvis 1200 eller -500.';return}game.players[i].score=value;save();closeModal();render();notify('Poängen för '+game.players[i].name+' har uppdaterats')}
function beginHold(e,i){if(game.locked)return;cancelHold();hold=setTimeout(()=>{hold=null;openPicker(i)},1000)}
function cancelHold(){clearTimeout(hold);hold=null}
function categoryKey(e,i){if(e.key==='Enter'||e.key===' '){e.preventDefault();if(!game.locked)openPicker(i)}}
function openPicker(i){if(game.locked)return;pickerIndex=i;modal(`<div class="dialog-head"><div><div class="eyebrow">Byt kategori</div><h2>${esc(game.board[i].name)}</h2></div><button class="close" aria-label="Stäng" onclick="closeModal()">×</button></div><input class="search" type="search" id="category-search" placeholder="Sök bland 200 kategorier…" aria-label="Sök kategori" oninput="filterCategories(this.value)"><p class="hint" style="margin-bottom:14px">Alla 200 kategorier är spelbara i 0.11. Tidigare rundors kategorier kan inte väljas igen.</p><div class="picker-list" id="picker-list"></div>`);filterCategories('')}
function reservedForLater(id){const seen=new Set(game.roundCategories||game.board.map(c=>c.id));return !seen.has(id)&&BANK.filter(c=>!game.usedCategories.includes(c.id)&&!seen.has(c.id)).length<=(3-game.round)*6}
function filterCategories(term){const names=ALL_CATEGORIES.filter(n=>n.toLocaleLowerCase('sv').includes(term.toLocaleLowerCase('sv')));$('#picker-list').innerHTML=names.map(name=>{const c=BANK.find(c=>c.name===name);let status=!c?'Kommer i frågebanken':game.usedCategories.includes(c.id)?'Spelad i tidigare omgång':game.board.some(b=>b.id===c.id)?'Finns på spelplanen':reservedForLater(c.id)?'Sparas till senare omgångar':'';return `<button ${status?'disabled':''} ${c&&!status?`onclick="replaceCategory('${c.id}')"`:''}>${esc(name)}${status?`<small>${status}</small>`:''}</button>`}).join('')||'<p class="empty">Ingen kategori matchar din sökning.</p>'}
function replaceCategory(id){if(game.locked)return;const c=BANK.find(c=>c.id===id);if(!c||game.usedCategories.includes(id)||game.board.some(b=>b.id===id)||reservedForLater(id))return;game.roundCategories||=game.board.map(b=>b.id);const seen=new Set([...game.usedAnswers,...game.board.filter((_,i)=>i!==pickerIndex).flatMap(b=>b.cells.map(q=>q.key))]);game.board[pickerIndex]=drawCategory(c,seen);game.roundCategories=[...new Set([...(game.roundCategories||game.board.map(b=>b.id)),id])];save();closeModal();render();notify('Kategorin har bytts ut')}
function rerollBoard(){if(active||roundTransitioning||game.phase!=='board'||game.locked)return;game.roundCategories||=game.board.map(c=>c.id);const excluded=new Set([...game.usedCategories,...game.roundCategories]),reserve=(3-game.round)*6,candidates=BANK.filter(c=>!excluded.has(c.id));if(candidates.length<6+reserve){notify('Det finns inte tillräckligt många oanvända kategorier kvar för en ny hel spelplan.');return}QuizEffects.scramble();const previous=game.board.map(c=>c.id),chosen=shuffle(candidates).slice(0,6),seen=new Set(game.usedAnswers);game.board=chosen.map(c=>drawCategory(c,seen));game.roundCategories=[...new Set([...game.roundCategories,...previous,...chosen.map(c=>c.id)])];game.doubleCell=Math.floor(Math.random()*30);save();render();notify('Alla sex kategorier har slumpats om')}
function confirmEndRound(){if(active||roundTransitioning||game.phase!=='board')return;const left=game.board.flatMap(c=>c.cells).filter(q=>!q.done).length;modal(`<div class="eyebrow">Omgång ${game.round}</div><h2>Avsluta omgången?</h2><p class="message">${left?`${left} ospelade rutor lämnas utan poäng.`:'Alla rutor är redan spelade.'} Nästa omgång följer de vanliga reglerna för vem som börjar.</p><div class="judge"><button onclick="closeModal()">Avbryt</button><button class="primary" onclick="endRoundNow()">Avsluta omgång →</button></div>`)}
function endRoundNow(){if(active||roundTransitioning)return;roundTransitioning=true;closeModal();QuizEffects.roundEnd();setTimeout(()=>{roundTransitioning=false;nextRound(true)},QuizEffects.enabled?6900:0)}

function openClue(ci,li){if(active||game.board[ci].cells[li].done)return;QuizEffects.unlock();QuizEffects.levelSelect();game.locked=true;const q=game.board[ci].cells[li];active={ci,li,question:q,category:game.board[ci].name,double:ci*5+li===game.doubleCell,stage:ci*5+li===game.doubleCell?'bet':'clue',selected:ci*5+li===game.doubleCell?game.chooser:null,failed:[],remaining:game.seconds*1000,running:false,reveal:false,resolved:false,message:'',wager:1};undo=null;save();render();if(active.double){const current=active;modal('<div class="double-intro"><div class="eyebrow">En dold chans har hittats</div><h2>Dubbelchans!</h2></div>',true);QuizEffects.celebrate('double',()=>{if(active===current)showActive()},$('#dialog'))}else showActive()}
function showActive(){if(!active)return;if(active.stage==='bet')return showDoubleBet();const a=active;modal(`<div class="dialog-head"><div><div class="eyebrow">${a.double?'Dubbelchans':`Omgång ${game.round}`} · ${fmt(a.double?a.wager:a.question.value)} poäng</div><h2>${esc(a.category)}</h2></div><span class="version">${a.li+1}/5</span></div><p class="clue">${esc(a.question.clue)}</p>${a.message?`<div class="message" role="status">${esc(a.message)}</div>`:''}${a.resolved?'':`<div class="timer-row" id="timer"><span class="timer-number" id="timer-number">${Math.ceil(a.remaining/1000)} s</span><div class="timer-track"><div class="timer-bar" id="timer-bar"></div></div><button id="timer-button" onclick="toggleTimer()" ${a.selected===null?'disabled':''}>${a.running?'Pausa':'Starta tid'}</button></div><div class="form-section"><label>${a.double?'Endast den här spelaren får svara':'Vem svarar? Tryck på namnet för att starta tiden.'}</label><div class="players-choose">${game.players.map((p,i)=>`<button class="${i===a.selected?'selected':''}" ${a.failed.includes(i)||(a.double&&i!==a.selected)?'disabled':''} onclick="selectRespondent(${i})">${esc(p.name)}${a.failed.includes(i)?' · försökt':''}</button>`).join('')}</div><div class="judge"><button class="right" onclick="judge(true)" ${a.selected===null?'disabled':''}>✓ Rätt</button><button class="wrong" onclick="judge(false)" ${a.selected===null?'disabled':''}>× Fel</button></div></div>`}<div id="answer-area">${answerHTML(a.question.answer,a.reveal)}</div><div class="dialog-bottom"><button onclick="toggleAnswer()">${a.reveal?'Dölj':'Visa'} facit</button>${undo?'<button onclick="undoJudge()">Ångra bedömning</button>':''}${a.resolved?'<button class="primary" onclick="finishClue()">Till spelplanen →</button>':'<button class="subtle" onclick="noMoreAnswers()">Inget svar</button>'}</div>`,true);updateTimerDisplay()}
function answerHTML(answer,revealed=true){return `<div class="answer"><strong class="${revealed?'':'answer-blurred'}" ${revealed?'':'aria-hidden="true"'}>${esc(answer)}</strong></div>`}
function maxBet(i){return game.players[i].score>0?game.players[i].score:1500}
function showDoubleBet(){const a=active;modal(`<div class="eyebrow">En dold chans har hittats</div><h2 style="font-size:2.4rem;margin:12px 0;color:var(--accent)">Dubbelchans!</h2><p class="message">Bara spelaren som valde rutan får svara. Välj namnet och bestäm insatsen innan ledtråden visas.</p><div class="stack"><label for="double-player">Spelaren som valde rutan</label><select id="double-player" onchange="setDoublePlayer(this.value)">${game.players.map((p,i)=>`<option value="${i}" ${i===a.selected?'selected':''}>${esc(p.name)} · ${fmt(p.score)} poäng</option>`).join('')}</select><label for="double-bet">Insats · 1–${fmt(maxBet(a.selected))} poäng${game.players[a.selected].score<=0?' (lån)':''}</label><input id="double-bet" type="number" inputmode="numeric" min="1" max="${maxBet(a.selected)}" value="${Math.min(a.wager,maxBet(a.selected))}"><p id="bet-error" class="error" role="alert"></p><button class="primary" onclick="revealDouble()">Lås insats och visa ledtråd</button></div>`)}
function setDoublePlayer(v){const i=+v;if(!game.players[i])return;active.selected=i;active.wager=1;save();showDoubleBet()}
function revealDouble(){const n=Number($('#double-bet').value);if(!Number.isInteger(n)||n<1||n>maxBet(active.selected)){$('#bet-error').textContent='Ange en hel insats inom det tillåtna intervallet.';return}active.wager=n;active.stage='clue';active.deadline=Date.now()+active.remaining;active.running=true;save();showActive()}
function pauseTimer(){if(active?.running){active.remaining=Math.max(0,active.deadline-Date.now());active.running=false}}
function toggleTimer(){if(!active||active.resolved||active.selected===null)return;if(active.running)pauseTimer();else{if(active.remaining<=0)active.remaining=game.seconds*1000;active.deadline=Date.now()+active.remaining;active.running=true}save();updateTimerDisplay()}
function selectRespondent(i){if(!active||active.stage!=='clue'||active.resolved||!game.players[i]||active.failed.includes(i)||(active.double&&i!==active.selected))return;pauseTimer();active.selected=i;active.deadline=Date.now()+active.remaining;active.running=true;save();showActive()}
function updateTimerDisplay(){if(!active)return;const n=$('#timer-number'),bar=$('#timer-bar'),button=$('#timer-button');if(n)n.textContent=Math.ceil(active.remaining/1000)+' s';if(bar)bar.style.width=Math.max(0,Math.min(100,active.remaining/(game.seconds*1000)*100))+'%';if(button)button.textContent=active.running?'Pausa':active.remaining===game.seconds*1000?'Starta tid':'Fortsätt';$('#timer')?.classList.toggle('expired',active.remaining<=0)}
function judge(right,timeout=false){if(!active||active.resolved||active.selected===null||active.stage!=='clue')return;pauseTimer();undo=snapshot();const a=active,i=a.selected,value=a.double?a.wager:a.question.value;game.players[i].score+=right?value:-value;a.running=false;if(right){game.chooser=i;a.resolved=true;a.message=`${game.players[i].name} får ${fmt(value)} poäng och väljer nästa ruta.`}else{QuizEffects.wrong();a.failed.push(i);a.message=`${game.players[i].name}: −${fmt(value)} poäng${timeout?' · tiden är slut':''}.`;if(a.double||a.failed.length===game.players.length){a.resolved=true;a.message+=' Ingen mer kan svara på den här rutan.'}else{a.message+=' Övriga spelare får försöka. Välj vem som svarar.';a.selected=null;a.remaining=game.seconds*1000}}if(right){finishClue();return}save();render();showActive()}
function noMoreAnswers(){if(!active||active.resolved)return;pauseTimer();undo=snapshot();active.resolved=true;active.message='Inget svar. Poängen är oförändrade. Föregående väljare behåller valet.';finishClue()}
function undoJudge(){if(!undo)return;({game,active}=JSON.parse(JSON.stringify(undo)));undo=null;active.running=false;if(active.remaining<=0)active.remaining=game.seconds*1000;save();render();showActive()}
function toggleAnswer(){if(!active)return;active.reveal=!active.reveal;save();showActive()}
function finishClue(){if(!active?.resolved)return;const q=game.board[active.ci].cells[active.li];q.done=true;if(!game.usedAnswers.includes(q.key))game.usedAnswers.push(q.key);active=null;undo=null;const complete=game.board.every(c=>c.cells.every(q=>q.done));if(complete&&game.roundEndSoundRound!==game.round){game.roundEndSoundRound=game.round;QuizEffects.roundEnd()}save();closeModal();render()}
function nextRound(force=false){if(active)return;const complete=game.board.every(c=>c.cells.every(q=>q.done));if(!complete&&!force)return;game.usedCategories=[...new Set([...game.usedCategories,...(game.roundCategories||[]),...game.board.map(c=>c.id)])];game.usedAnswers=[...new Set([...game.usedAnswers,...game.board.flatMap(c=>c.cells.map(q=>q.key))])];if(game.round===3)return startFinal();const low=Math.min(...game.players.map(p=>p.score)),candidates=game.players.map((p,i)=>p.score===low?i:-1).filter(i=>i>=0);if(candidates.length===1)beginNextRound(candidates[0]);else modal(`<div class="eyebrow">Nästa omgång</div><h2>Vem börjar?</h2><p class="message">Flera spelare har lägst poäng (${fmt(low)}). Du väljer vem som börjar.</p><div class="round-choices">${candidates.map(i=>`<button onclick="beginNextRound(${i})">${esc(game.players[i].name)}</button>`).join('')}</div>`)}
function beginNextRound(i){game.round++;game.chooser=i;makeBoard();save();closeModal();render();QuizEffects.roundIntro()}
function startFinal(){QuizEffects.stopFinalThinking();const eligible=game.players.map((p,i)=>p.score>0?i:-1).filter(i=>i>=0);closeModal();if(!eligible.length){game.phase='result';game.noFinal=true;save();render();return}const q=shuffle(FINALS.filter(q=>!game.usedAnswers.includes(q.key)))[0];game.phase='final';game.final={question:q,eligible,bets:{},results:{},stage:'bet',remaining:game.finalSeconds*1000,running:false,reveal:false};save();render()}
function renderFinal(){const f=game.final;$('#app').innerHTML=`<main class="shell">${header()}<section class="final-screen"><div class="eyebrow">Den sista utmaningen</div><h1>Final<span style="color:var(--accent)">rundan</span></h1><div class="panel"><div class="eyebrow">Kategori</div><h2 style="margin-top:8px">${esc(f.question.category)}</h2>${f.stage==='bet'?`<p class="message">Satsa innan ledtråden visas. Skriv era insatser på papper och låt spelledaren registrera dem. Endast spelare med pluspoäng deltar.</p>${f.eligible.map(i=>`<div class="bet-row"><label for="final-bet-${i}">${esc(game.players[i].name)}<small>1–${fmt(game.players[i].score)} poäng</small></label><input id="final-bet-${i}" aria-label="Insats för ${esc(game.players[i].name)}" type="number" inputmode="numeric" min="1" max="${game.players[i].score}" value="${f.bets[i]||1}"></div>`).join('')}<p class="error" id="final-error" role="alert"></p><button class="primary wide" onclick="lockFinalBets()">Lås alla insatser och visa ledtråd</button>`:`<p class="final-clue">${esc(f.question.clue)}</p><p class="hint">Skriv frågeformuleringen på papper. Visa den när spelledaren ber om det.</p>${f.stage==='clue'?`<div class="timer-row"><span class="timer-number" id="final-time">${Math.ceil(f.remaining/1000)} s</span><div class="timer-track"><div class="timer-bar" id="final-bar"></div></div><button id="final-timer-button" onclick="toggleFinalTimer()">${f.running?'Pausa':'Starta tid'}</button></div><button class="wide subtle" style="margin-top:24px" onclick="endFinalThinking()">Alla är klara – gå till rättning</button>`:`<div class="message">Betänketiden är avslutad. Visa facit och bedöm ett svar i taget.</div><button onclick="toggleFinalAnswer()">${f.reveal?'Dölj':'Visa'} facit</button>${answerHTML(f.question.answer,f.reveal)}<div class="form-section">${f.eligible.map(i=>`<div class="stack" style="margin-bottom:20px"><div class="row"><strong>${esc(game.players[i].name)}</strong><span class="meta">Insats ${fmt(f.bets[i])}</span></div><div class="judge" style="margin:0"><button class="right" ${f.results[i]===true?'aria-pressed="true" style="border-width:3px"':''} onclick="gradeFinal(${i},true)">✓ Rätt${f.results[i]===true?' · valt':''}</button><button class="wrong" ${f.results[i]===false?'aria-pressed="true" style="border-width:3px"':''} onclick="gradeFinal(${i},false)">× Fel / inget svar${f.results[i]===false?' · valt':''}</button></div></div>`).join('')}</div><button class="primary wide" ${f.eligible.some(i=>typeof f.results[i]!=='boolean')?'disabled':''} onclick="finishFinal()">Visa slutresultat →</button>`}`}</div></section></main>`;updateFinalTimer()}
function lockFinalBets(){const f=game.final;const bets={};for(const i of f.eligible){const n=Number($('#final-bet-'+i).value);if(!Number.isInteger(n)||n<1||n>game.players[i].score){$('#final-error').textContent='Kontrollera insatsen för '+game.players[i].name+'.';return}bets[i]=n}f.bets=bets;f.stage='clue';f.running=true;f.deadline=Date.now()+f.remaining;save();render();QuizEffects.startFinalThinking(game.finalSeconds||45,true)}
function toggleFinalTimer(){const f=game.final;if(f.running){f.remaining=Math.max(0,f.deadline-Date.now());f.running=false;QuizEffects.pauseFinalThinking()}else{f.deadline=Date.now()+f.remaining;f.running=true;QuizEffects.startFinalThinking(game.finalSeconds||45,false)}save();updateFinalTimer()}
function updateFinalTimer(){if(game?.phase!=='final')return;const f=game.final;if($('#final-time'))$('#final-time').textContent=Math.ceil(f.remaining/1000)+' s';if($('#final-bar'))$('#final-bar').style.width=f.remaining/(game.finalSeconds*1000)*100+'%';if($('#final-timer-button'))$('#final-timer-button').textContent=f.running?'Pausa':'Fortsätt'}
function endFinalThinking(){game.final.running=false;game.final.stage='grade';QuizEffects.stopFinalThinking();save();render()}
function toggleFinalAnswer(){game.final.reveal=!game.final.reveal;save();render()}
function gradeFinal(i,right){if(!game.final.eligible.includes(i))return;game.final.results[i]=right;save();render()}
function finishFinal(){const f=game.final;if(f.eligible.some(i=>typeof f.results[i]!=='boolean'))return;QuizEffects.stopFinalThinking();f.eligible.forEach(i=>game.players[i].score+=f.results[i]?f.bets[i]:-f.bets[i]);game.phase='result';save();render()}
function renderResults(){const sorted=game.players.map((p,i)=>({...p,i})).sort((a,b)=>b.score-a.score),winners=sorted.filter(p=>p.score===sorted[0].score);$('#app').innerHTML=`<main class="shell">${header()}<section class="final-screen"><div class="eyebrow">Partiet är avslutat</div><h1 class="result-title">${winners.length>1?'Delad seger!':'Vilken match!'}</h1><h2>${winners.map(p=>esc(p.name)).join(' & ')}${winners.length>1?' delar förstaplatsen':' vinner QuizStorm'}</h2>${game.noFinal?'<p class="message">Ingen spelare hade pluspoäng. Finalen spelades därför inte.</p>':''}<div class="panel">${sorted.map((p,i)=>`<div class="rank"><span class="place">${sorted.findIndex(x=>x.score===p.score)+1}</span><span>${esc(p.name)}</span><strong class="${p.score<0?'negative':''}">${fmt(p.score)}</strong></div>`).join('')}</div><button class="primary wide" style="margin-top:24px" onclick="renderMenu()">Till huvudmenyn</button></section></main>`;QuizEffects.celebrate('winner')}
function showRules(){if(active)pauseTimer();if(game?.phase==='final'&&game.final.running)toggleFinalTimer();modal(`<div class="dialog-head"><h2>Så spelar ni QuizStorm</h2><button class="close" aria-label="Stäng" onclick="returnFromInfo()">×</button></div><div class="stack"><p>Välj en kategori och en poängruta. Spelledaren läser ledtråden. Spelaren svarar som en fråga: <strong>”Vem är …?”</strong> eller <strong>”Vad är …?”</strong></p><p>Markera spelaren som svarar. Rätt ger plus. Fel svar ger minus, liksom utgången tid för en spelare som har anmält sig och markerats som svarande. Knappen ”Inget svar” avslutar rutan utan att ändra någons poäng. Övriga får därefter ett försök var. När spelledaren markerar nästa svarande startar den spelarens svarstid automatiskt. Pausknappen stoppar tiden tillfälligt.</p><p>Den som svarar rätt väljer nästa ruta. Om ingen lyckas behåller föregående väljare turen. Lägst poäng börjar nästa omgång; spelledaren avgör vid lika.</p><p>En dold dubbelchans finns per omgång. Bara den som valde rutan får svara och satsar 1 poäng upp till sin poängsumma. Vid noll eller minus tillåts en insats på upp till 1 500.</p><p>Inför finalen visas kategorin. Spelare med pluspoäng satsar 1 poäng upp till hela sin poängsumma och skriver sin frågeformulering på papper. Rätt eller fel ger plus eller minus insatsen.</p><p>Svårighetsgraden väljs före ett nytt parti. <strong>Lätt</strong> använder poolerna 100, 200, 300, 300, 300. <strong>Normal</strong> använder 100, 200, 300, 400, 500 precis som tidigare. <strong>Svår</strong> använder 300, 400, 400, 500, 500. Rutornas poängvärden ändras inte, och Finalens separata frågepool påverkas inte.</p><p>Ljud på/av styr ljudeffekter och musik. Huvudmenyn har egen bakgrundsmusik och ett nytt parti öppnas med en särskild startsekvens. Omgång 2 och 3 får en kort gameshow-intro och en färdig spelplan en avslutningssignal. Under Finalens nedräkning används en egen 30-, 45- eller 60-sekunders musikversion som pausar och fortsätter tillsammans med klockan och slutar vid noll. Vinnaren firas med loopande gameshow-musik och fyrverkerier tills vinnarskärmen lämnas. Effekterna förbrukar ingen svarstid.</p><p>Om en poängsumma blivit fel: håll inne spelarens namn ovanför spelplanen i en sekund. Ange den korrekta totala poängsumman, även minuspoäng, och tryck på Spara poäng. Avbryt lämnar poängen oförändrade.</p><p>Håll inne en kategori i en sekund för att byta före första öppnade rutan. Tärningen 🎲 uppe till höger slumpar om alla sex kategorier före första frågan. Pilen → avslutar den aktuella omgången efter en bekräftelse. Samma kategori återkommer inte i senare rundor.</p><p class="test-note">0.11: tre valbara svårighetsgrader, 200 kategorier, fem alternativ per nivå och 120 separata finalledtrådar. En ledtråd slumpas per ruta och sparas med partiet. Samma facit återkommer inte. Svårigheten följer nivån, medan poängen ökar mellan omgångarna. Vid lika slutpoäng delas segern. Ingen spelare är automatiskt anmäld på vanliga frågor. Markera den som anmäler sig så startar svarstiden automatiskt.</p></div>`);save()}
function returnFromInfo(){closeModal();if(active)showActive()}
function showTools(){modal(`<div class="dialog-head"><h2>Spelmeny</h2><button class="close" aria-label="Stäng" onclick="closeModal()">×</button></div><div class="stack"><button onclick="closeModal();renderMenu()">Till huvudmenyn · partiet sparas</button><details><summary>Testverktyg för version 0.11</summary><p class="message">Avsluta omgången i förtid för att prova nästa runda eller finalen. Ospelade rutor ger inga poäng.</p><button onclick="closeModal();nextRound(true)">Avsluta omgång ${game.round}</button></details><p class="hint">Partiet sparas på den här telefonen. Tiden pausas om du lämnar fliken.</p></div>`)}
$('#dialog').addEventListener('cancel',e=>{if(active){e.preventDefault();pauseTimer();showActive();save()}else if($('#dialog').textContent.includes('Vem börjar?'))e.preventDefault()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseTimer();if(game?.phase==='final'&&game.final.running){game.final.remaining=Math.max(0,game.final.deadline-Date.now());game.final.running=false;QuizEffects.pauseFinalThinking()}save();updateTimerDisplay();updateFinalTimer()}else if(game?.phase==='result'){QuizEffects.celebrate('winner')}});
setInterval(()=>{if(active?.running){active.remaining=Math.max(0,active.deadline-Date.now());updateTimerDisplay();if(active.remaining===0){active.running=false;judge(false,true)}}if(game?.phase==='final'&&game.final.running){game.final.remaining=Math.max(0,game.final.deadline-Date.now());updateFinalTimer();if(game.final.remaining===0)endFinalThinking()}},150);
window.addEventListener('pagehide',()=>{pauseTimer();save()});
// Optional browser-standard read tool. Never returns hidden questions or final answers.
try{if(document.modelContext?.registerTool){const lifecycle=new AbortController();document.modelContext.registerTool({name:'get_quizstorm_status',description:'Read the visible QuizStorm phase, round and player scores. Does not reveal hidden clues or answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return game?{phase:game.phase,round:game.round,difficulty:game.difficulty||'normal',players:game.players.map(p=>({...p})),chooser:game.players[game.chooser].name}:{phase:'menu'}}},{signal:lifecycle.signal});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}}catch{}
document.addEventListener('click',e=>{if(!document.body.classList.contains('playing')&&!e.target?.closest?.('.start,[onclick*=\"resumeGame\"]'))QuizEffects.menuMusic(false)});
document.addEventListener('keydown',()=>{if(!document.body.classList.contains('playing'))QuizEffects.menuMusic(false)});
renderMenu();
